        "99fb07fe351d4d22aaf5409e65363c3c": {
          "id": "99fb07fe351d4d22aaf5409e65363c3c",
          "name": "get_claim_status",
          "script": "(function execute() {\n\n    var claim = new GlideRecord('x_snc_insurance_0_claim');\n\n    claim.addQuery('claim_number', vaInputs.claim_number_input);\n\n    claim.setLimit(1);\n    claim.query();\n\n    if (claim.next()) {\n        vaVars.claim_status = claim.getDisplayValue('status');\n    } else {\n        vaVars.claim_status = 'Claim not found';\n    }\n\n})()",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
